#include <queue>
#include <tuple>
#include <vector>
int main() {
    std::ifstream in("visitfj.in");std::ofstream out("visitfj.out");
    int n;long long t;in >> n >> t;std::vector<std::vector<long long>> grass(n,std::vector<long long>(n));for(auto& row:grass) for(auto& x:row) in >> x;
    const long long inf=std::numeric_limits<long long>::max()/4;
    std::vector<std::vector<std::array<long long,3>>> dist(n,std::vector<std::array<long long,3>>(n,{inf,inf,inf}));
    using State=std::tuple<long long,int,int,int>;
    std::priority_queue<State,std::vector<State>,std::greater<State>> queue;
    dist[0][0][0]=0;queue.push({0,0,0,0});const int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
    while(!queue.empty()) {
        auto [cost,r,c,phase]=queue.top();queue.pop();if(cost!=dist[r][c][phase]) continue;
        for(int direction=0;direction<4;++direction) {
            int rr=r+dr[direction],cc=c+dc[direction];if(rr<0||rr>=n||cc<0||cc>=n) continue;
            int next=(phase+1)%3;long long value=cost+t+(next==0?grass[rr][cc]:0);
            if(value<dist[rr][cc][next]) {dist[rr][cc][next]=value;queue.push({value,rr,cc,next});}
        }
    }
    out << *std::min_element(dist[n-1][n-1].begin(),dist[n-1][n-1].end()) << '\n';
}
