int main() {
    std::ifstream in("nocross.in");std::ofstream out("nocross.out");
    int n;in >> n;std::vector<int> a(n),b(n);for(auto& x:a) in >> x;for(auto& x:b) in >> x;
    std::vector<int> previous(n+1,0),current(n+1,0);
    for(int i=1;i<=n;++i) {
        current[0]=0;
        for(int j=1;j<=n;++j) {
            current[j]=std::max(previous[j],current[j-1]);
            if(std::abs(a[i-1]-b[j-1])<=4) current[j]=std::max(current[j],previous[j-1]+1);
        }
        previous.swap(current);
    }
    out << previous[n] << '\n';
}
