    std::ifstream in("circlecross.in");std::ofstream out("circlecross.out");
    int n;in >> n;std::vector<int> first(n,-1),tree(2*n+1,0);
    auto add=[&](int index,int delta){for(;index<=2*n;index+=index&-index) tree[index]+=delta;};
    auto sum=[&](int index){int result=0;for(;index>0;index-=index&-index) result+=tree[index];return result;};
    long long answer=0;
    for(int position=1;position<=2*n;++position) {
        int cow;in >> cow;--cow;
        if(first[cow]==-1) {first[cow]=position;add(position,1);}
        else {answer+=sum(position-1)-sum(first[cow]);add(first[cow],-1);}
    }
